function v3_report_e2(T,out)
writetable(T,fullfile(out,'tables','E2_controller_comparison.csv'));f=figure('Visible','off');tiledlayout(1,3);for a=[5 10 15],nexttile;hold on;S=T(T.amplitude_deg==a & startsWith(string(T.pair_id),'V2_S'),:);for k=1:height(S),D=readtable(fullfile(out,'E2','cases',char(string(S.id(k))),'timeseries.csv'));idx=1:max(1,ceil(height(D)/2000)):height(D);plot(D.time_s(idx),D.pitch_deg(idx),'Color',v3_color(S.method(k)),'DisplayName',char(string(S.method(k))));if k==1,plot(D.time_s(idx),D.ref_pitch_deg(idx),'k--','DisplayName','Reference');end;end;title(sprintf('Pitch +%d deg',a));xlabel('Time (s)');ylabel('Pitch (deg)');legend('Interpreter','none','Location','best');grid on;end;v3_savefig(f,out,'E2_single');
S=T(startsWith(string(T.pair_id),'V2_M'),:);writetable(S,fullfile(out,'tables','E2_unload_following_task.csv'));for task=1:2,f=figure('Visible','off');tiledlayout(3,1);M=S(strcmp(S.pair_id,sprintf('V2_M%d',task)),:);for k=1:height(M),D=readtable(fullfile(out,'E2','cases',char(string(M.id(k))),'timeseries.csv'));idx=1:max(1,ceil(height(D)/2000)):height(D);nexttile(1);hold on;plot(D.time_s(idx),sqrt(D.Hx_Nms(idx).^2+D.Hy_Nms(idx).^2+D.Hz_Nms(idx).^2),'Color',v3_color(M.method(k)),'DisplayName',char(string(M.method(k))));nexttile(2);hold on;plot(D.time_s(idx),D.attitude_error_deg(idx),'Color',v3_color(M.method(k)),'DisplayName',char(string(M.method(k))));nexttile(3);hold on;plot(D.time_s(idx),D.aero_y_Nm(idx)+D.cmg_y_Nm(idx),'Color',v3_color(M.method(k)),'DisplayName',char(string(M.method(k))));end;labels={'|H| (N m s)','Attitude error (deg)','Actual control pitch (Nm)'};for j=1:3,nexttile(j);ylabel(labels{j});legend('Interpreter','none');grid on;end;xlabel('Time (s)');v3_savefig(f,out,sprintf('E2_unload_%d',task));end
end
